import re
with open('backend/hono.ts') as f:
    lines = f.readlines()

routes = []
for i, line in enumerate(lines[:3300], 1):
    m = re.match(r"app\.(get|post|put|delete|options|all)\(['\"]([^'\"]+)['\"],", line.strip())
    if m:
        method, path = m.groups()
        routes.append((i, method, path))

# Find routes that could match /api/ivx/outreach (GET)
target = '/api/ivx/outreach'
for i, method, path in routes:
    if method != 'get':
        continue
    # Simple pattern matching: exact, param segments, wildcard
    if path == target or path == target + '/':
        print(f'EXACT: line {i}: {path}')
    elif path.endswith('*') and target.startswith(path.rstrip('*')):
        print(f'WILDCARD: line {i}: {path}')
